;------------------------------------------------------------------------------
; InExodusCastle: ZF set (AL = 0FFh) when the party is in the castle of Exodus: Location 3
; (a castle), or a fight (80h) that started in one, and the saved entry position's x is
; the castle's (ExodusCastleX: the second (x, y) pair of the map table, EXODUS.ULT). Only x is
; compared. Out: ZF, AL = 0FFh yes / 0 no. Callers: the main loop, COMBAT.
;------------------------------------------------------------------------------
InExodusCastle:	pushf	;@5B28
	cmp byte ptr Location, 80h	; 80h: a fight	;@5B29
	je InExodus_Combat	;@5B2E
	cmp byte ptr Location, 3	; 3: a castle	;@5B30
	jne InExodus_No	;@5B35
InExodus_CheckX:	mov al, byte ptr PartyXY	;@5B37
	cmp al, byte ptr ExodusCastleX	; the x of EXODUS.ULT's entrance	;@5B3A
	jne InExodus_No	;@5B3E
	mov al, 0FFh	;@5B40
InExodus_Ret:	popf	;@5B42
	cmp al, 0FFh	;@5B43
	ret	;@5B45
InExodus_Combat:	cmp byte ptr SavedLocation, 3	;@5B46
	je InExodus_CheckX	;@5B4B
InExodus_No:	mov al, 0	;@5B4D
	jmp InExodus_Ret	;@5B4F
;------------------------------------------------------------------------------
; MoonGateJump: the party stepped on a moon gate (map byte 88h, shape 34): flash, move to the
; gate of the second moon's phase (GateXTbl/GateYTbl), sound and flash again.
; Uses: nothing (saves AX, BX). Callers: the main loop (1C15, 1C2B).
;------------------------------------------------------------------------------
MoonGateJump:	push ax	;@5B51
	push bx	;@5B52
	call BuildView	;@5B53
	call FlashView	; FlashView	;@5B56
	mov bl, byte ptr Moon2Phase	;@5B59
	mov bh, 0	;@5B5D
	mov al, byte ptr GateXTbl[bx]	;@5B5F
	mov ah, byte ptr GateYTbl[bx]	;@5B63
	mov word ptr PlayerXY, ax	;@5B67
	mov bl, 0C0h	; sound 0FDh: BL, BH = its parameters (?)	;@5B6A
	mov bh, 20h	;@5B6C
	mov al, 0FDh	;@5B6E
	call Sound	;@5B70
	call FlashView	; FlashView	;@5B73
	call BuildView	;@5B76
	call FlashView	; FlashView	;@5B79
	call Sound	; the same sound again	;@5B7C
	call FlashView	; FlashView	;@5B7F
	pop bx	;@5B82
	pop ax	;@5B83
	ret	;@5B84
;------------------------------------------------------------------------------
; DexRoll: a roll against the dexterity of the player at BX: chance = (Dex + bonus) / 255,
; bonus 128 for a thief, 64 for a barbarian, illusionist or ranger, else 0.
; In: BX = record. Out: ZF set = success. Callers: Steal (LOOP 1F72), traps (DUNMOVE
; 82AF), DUNEVENT 953C.
;------------------------------------------------------------------------------
DexRoll:	pushf	;@5B85
	push dx	;@5B86
	mov dh, ah	;@5B87
	mov al, byte ptr [bx+13h]	; dexterity (BCD)	;@5B89
	mov ah, 0	;@5B8C
	shl ax, 1	;@5B8E
	shl ax, 1	;@5B90
	shl ax, 1	;@5B92
	shl ax, 1	;@5B94
	mov al, byte ptr [bx+13h]	; AH = tens, AL = units	;@5B96
	and al, 0Fh	;@5B99
	aad	; AL = dexterity in binary	;@5B9B
	mov ah, dh	;@5B9D
	add al, 40h	;@5B9F
	cmp byte ptr [bx+17h], 42h	; class: 'B' barbarian	;@5BA1
	je DexRoll_Roll	;@5BA5
	cmp byte ptr [bx+17h], 49h	; 'I' illusionist	;@5BA7
	je DexRoll_Roll	;@5BAB
	cmp byte ptr [bx+17h], 52h	; 'R' ranger	;@5BAD
	je DexRoll_Roll	;@5BB1
	add al, 40h	;@5BB3
	cmp byte ptr [bx+17h], 54h	; 'T' thief	;@5BB5
	je DexRoll_Roll	;@5BB9
	sub al, 80h	;@5BBB
DexRoll_Roll:	mov dh, 0FFh	; Random: DL = 0..DH-1 (?)	;@5BBD
	call Random	;@5BBF
	cmp dl, al	; success when the roll is below	;@5BC2
	mov al, 0FFh	;@5BC4
	jae DexRoll_Done	;@5BC6
	mov al, 0	;@5BC8
DexRoll_Done:	pop dx	;@5BCA
	popf	;@5BCB
	cmp al, 0	;@5BCC
	ret	;@5BCE
;------------------------------------------------------------------------------
; CmdFire (F): fire the frigate's cannons in a direction: three cells, each flashing fire
; (map byte 0F4h, shape 61); the first creature in the line is hit with a chance of 1/2
; (a pirate ship, 3Ch, 1/4), and "<name>s Destroyed!" removes it. In: SI = the prompt.
;------------------------------------------------------------------------------
CmdFire:	call PrintMsg	;@5BCF
	cmp byte ptr PartyTile, 0Bh	; 0Bh: on a frigate	;@5BD2
	je Fire_OnShip	;@5BD7
	jmp MsgWhat	;@5BD9
Fire_OnShip:	lea si, MsgFireDirect	;@5BDC
	call PrintMsg	;@5BE0
	call AskDirection	; ask a direction: DX = step, ZF on Esc (?)	;@5BE3
	je Fire_Done	;@5BE6
	mov al, 0FBh	; sound 0FBh: the cannon	;@5BE8
	call Sound	;@5BEA
	mov cx, word ptr PlayerXY	;@5BED
	mov ax, dx	;@5BF1
	mov si, 3	; range: 3 cells	;@5BF3
Fire_Step:	add ch, ah	;@5BF6
	add cl, al	;@5BF8
	and cx, 3F3Fh	;@5BFA
	mov dx, cx	;@5BFE
	call FindMonster	; BX = the creature slot at DX, or -1 (?)	;@5C00
	cmp bx, -1	;@5C03
	jne Fire_Hit	;@5C06
	push ax	;@5C08
	mov bx, dx	;@5C09
	call MapCellAddr	;@5C0B
	mov byte ptr [bx], 0F4h	; fire on the map	;@5C0E
	call BuildView	;@5C11
	mov byte ptr [bx], al	; put the cell back	;@5C14
	pop ax	;@5C16
	dec si	;@5C17
	jne Fire_Step	;@5C18
Fire_Redraw:	call BuildView	;@5C1A
Fire_Done:	jmp MainLoop	;@5C1D
Fire_Hit:	mov di, bx	;@5C20
	mov bx, dx	;@5C22
	call MapCellAddr	;@5C24
	mov byte ptr [bx], 0F4h	;@5C27
	call BuildView	;@5C2A
	mov ah, al	;@5C2D
	mov al, 0F7h	; sound 0F7h	;@5C2F
	call Sound	;@5C31
	mov dh, 0FFh	;@5C34
	mov al, byte ptr MonTile[di]	;@5C36
	cmp al, 3Ch	; 3Ch: pirate ship (shape 15)	;@5C3A
	jne Fire_Roll	;@5C3C
	call Random	;@5C3E
	shl dl, 1	; bit 7: a 1/2 chance	;@5C41
	jae Fire_Miss	;@5C43
Fire_Roll:	call Random	;@5C45
	shl dl, 1	;@5C48
	jae Fire_Miss	;@5C4A
	mov al, byte ptr MonTile[di]	;@5C4C
	shr al, 1	; shape + 1 = name number	;@5C50
	shr al, 1	;@5C52
	add al, 1	;@5C54
	call PrintName	;@5C56
	lea si, MsgDestroyed	;@5C59
	call PrintMsg	;@5C5D
	mov al, ah	;@5C60
	mov cl, byte ptr MonUnder[di]	; the map byte under the creature	;@5C62
	mov byte ptr [bx], cl	;@5C66
	mov byte ptr MonTile[di], 0	; the slot is free	;@5C68
	jmp Fire_Done	;@5C6D
Fire_Miss:	mov byte ptr [bx], ah	;@5C6F
	jmp Fire_Redraw	;@5C71
;------------------------------------------------------------------------------
; CmdJoinGold (J): give the whole party's gold to one player. The sum is BCD; past 9999 it
; is "No more room!" and nothing changes. All four slots' gold is cleared, even past
; PartySize. In: SI = the prompt.
;------------------------------------------------------------------------------
CmdJoinGold:	call PrintMsg	;@5C73
	call AskPlayer	;@5C76
	je Join_Done	;@5C79
	mov di, bx	; DI = the receiver	;@5C7B
	lea bx, Players	;@5C7D
	mov si, bx	;@5C81
	mov cl, byte ptr PartySize	;@5C83
	mov ch, 0	;@5C87
	mov ax, 0	;@5C89
Join_Sum:	mov dx, word ptr [bx+23h]	; gold	;@5C8C
	add al, dl	;@5C8F
	daa	;@5C91
	xchg al, ah	;@5C92
	adc al, dh	;@5C94
	daa	;@5C96
	xchg al, ah	;@5C97
	jb Join_TooMuch	;@5C99
	add bx, 40h	;@5C9B
	loop Join_Sum	;@5C9E
	mov cx, 4	;@5CA0
	mov bx, si	;@5CA3
Join_Clear:	mov word ptr [bx+23h], 0	;@5CA5
	add bx, 40h	;@5CAA
	loop Join_Clear	;@5CAD
	mov word ptr [di+23h], ax	;@5CAF
Join_Done:	jmp MainLoop	;@5CB2
Join_TooMuch:	lea si, MsgNoMoreRoom	; "No more room!"	;@5CB5
	call PrintMsg	;@5CB9
	mov al, 0FFh	;@5CBC
	call Sound	;@5CBE
	jmp Join_Done	;@5CC1
;------------------------------------------------------------------------------
; CmdKlimbDescend (K, D on the surface): print the prompt, then "What?".
;------------------------------------------------------------------------------
CmdKlimbDescend:	call PrintMsg	;@5CC3
	jmp MsgWhat	;@5CC6
;------------------------------------------------------------------------------
; CmdIgnite (I): only in a dungeon: a player spends a torch, LightOn = 0FFh (it counts down
; with the moves, DUNMOVE 839D). In: SI = the prompt.
;------------------------------------------------------------------------------
CmdIgnite:	call PrintMsg	;@5CC9
	cmp byte ptr Location, 1	; 1: a dungeon	;@5CCC
	jne Ignite_NotHere	;@5CD1
	lea si, MsgWhoseTorch	;@5CD3
	call PrintMsg	;@5CD7
	call AskPlayer	;@5CDA
	je Ignite_Done	;@5CDD
	mov al, byte ptr [bx+0Fh]	; torches (BCD)	;@5CDF
	sub al, 1	;@5CE2
	das	;@5CE4
	jb Ignite_NoneLeft	;@5CE5
	mov byte ptr [bx+0Fh], al	;@5CE7
	mov byte ptr LightOn, 0FFh	;@5CEA
Ignite_Done:	jmp MainLoop	;@5CEF
Ignite_NotHere:	jmp MsgNotHere	;@5CF2
Ignite_NoneLeft:	jmp MsgNoneLeft	;@5CF5
;------------------------------------------------------------------------------
; CmdNegate (N): a player spends a powder, TimeStop = 10 (the creatures stand still).
; In: SI = the prompt.
;------------------------------------------------------------------------------
CmdNegate:	call PrintMsg	;@5CF8
	call AskPlayer	;@5CFB
	je Negate_Done	;@5CFE
	mov al, byte ptr [bx+27h]	; powders (BCD)	;@5D00
	sub al, 1	;@5D03
	das	;@5D05
	jb Negate_NoneLeft	;@5D06
	mov byte ptr [bx+27h], al	;@5D08
	mov byte ptr TimeStop, 0Ah	;@5D0B
Negate_Done:	jmp MainLoop	;@5D10
Negate_NoneLeft:	jmp MsgNoneLeft	;@5D13
;------------------------------------------------------------------------------
; ReadKeyUpper: ReadKey; AL = the key, AH = the key with a-z made upper case.
; Callers: CastSpell.
;------------------------------------------------------------------------------
ReadKeyUpper:	pushf	;@5D16
	call ReadKey	;@5D17
	mov ah, al	;@5D1A
	cmp ah, 61h	; 'a'	;@5D1C
	jb ReadKeyUp_Done	;@5D1F
	cmp ah, 7Ah	; 'z'	;@5D21
	ja ReadKeyUp_Done	;@5D24
	add ah, 0E0h	;@5D26
ReadKeyUp_Done:	popf	;@5D29
	ret	;@5D2A
;------------------------------------------------------------------------------
; AddHitPoints: add AL (BCD) to the hit points of the record at BX, at most its maximum.
; Callers: HealPlayer.
;------------------------------------------------------------------------------
AddHitPoints:	pushf	;@5D2B
	push ax	;@5D2C
	add al, byte ptr [bx+1Ah]	; hit points (BCD word)	;@5D2D
	daa	;@5D30
	mov byte ptr [bx+1Ah], al	;@5D31
	mov al, byte ptr [bx+1Bh]	;@5D34
	adc al, 0	;@5D37
	daa	;@5D39
	mov byte ptr [bx+1Bh], al	;@5D3A
	mov ax, word ptr [bx+1Ch]	; maximum hit points	;@5D3D
	cmp ax, word ptr [bx+1Ah]	;@5D40
	jae AddHP_Done	;@5D43
	mov word ptr [bx+1Ah], ax	;@5D45
AddHP_Done:	pop ax	;@5D48
	popf	;@5D49
	ret	;@5D4A
;------------------------------------------------------------------------------
; AddExp: add AL (BCD) to the experience of BX, at most 9999. Callers: COMBAT 8FA7.
;------------------------------------------------------------------------------
AddExp:	pushf	;@5D4B
	push ax	;@5D4C
	add al, byte ptr [bx+1Eh]	; experience (BCD word)	;@5D4D
	daa	;@5D50
	mov byte ptr [bx+1Eh], al	;@5D51
	mov al, byte ptr [bx+1Fh]	;@5D54
	adc al, 0	;@5D57
	daa	;@5D59
	mov byte ptr [bx+1Fh], al	;@5D5A
	jae AddExp_Done	;@5D5D
	mov word ptr [bx+1Eh], 9999h	;@5D5F
AddExp_Done:	pop ax	;@5D64
	popf	;@5D65
	ret	;@5D66
;------------------------------------------------------------------------------
; AddGold: add AL (BCD) to the gold of BX, at most 9999. Callers: EQUIP 810A.
;------------------------------------------------------------------------------
AddGold:	pushf	;@5D67
	push ax	;@5D68
	add al, byte ptr [bx+23h]	; gold (BCD word)	;@5D69
	daa	;@5D6C
	mov byte ptr [bx+23h], al	;@5D6D
	mov al, byte ptr [bx+24h]	;@5D70
	adc al, 0	;@5D73
	daa	;@5D75
	mov byte ptr [bx+24h], al	;@5D76
	jae AddGold_Done	;@5D79
	mov word ptr [bx+23h], 9999h	;@5D7B
AddGold_Done:	pop ax	;@5D80
	popf	;@5D81
	ret	;@5D82
CODE ENDS
END
